package com.englishhero.reading.translation;
import java.nio.file.*;import java.util.*;import java.util.concurrent.TimeUnit;
import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;
import static org.assertj.core.api.Assertions.*;
class SelectionTranslationBrowserVerification extends SelectionTranslationHttpITSupport {
 @Autowired SelectionTranslationJobs jobs;@Autowired SelectionTranslationMapper mapper;
 @Test void actualJwtReadingSelectionUsesPersistentCachedTask()throws Exception{var admin=actor(true);var user=actor(false);var input=published(admin);long uid=jdbc.queryForObject("SELECT id FROM identity_user WHERE username=?",Long.class,accounts.get(user).get("username"));Path root=Path.of("..").toAbsolutePath().normalize(),fixture=root.resolve(".tool-cache/selection-translation/browser-fixture.json");Files.createDirectories(fixture.getParent());Files.writeString(fixture,json.writeValueAsString(Map.of("port",port,"user",accounts.get(user),"article",input.get("articleId"))));try{var process=new ProcessBuilder("node",root.resolve("frontend/tests/real/selection-translation-browser.cjs").toString()).directory(root.toFile()).redirectErrorStream(true).redirectOutput(root.resolve(".tool-cache/selection-translation/real-browser.log").toFile()).start();long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(120);while(process.isAlive()&&System.nanoTime()<deadline){var queued=jdbc.query("SELECT * FROM reading_selection_translation WHERE user_id=? AND status='QUEUED'",mapper.jobs(),uid);for(var row:queued){String lease=UUID.randomUUID().toString();jdbc.update("UPDATE reading_selection_translation SET status='RUNNING',lease_token=?,lease_until=? WHERE id=? AND status='QUEUED'",lease,java.sql.Timestamp.from(java.time.Instant.now().plusSeconds(180)),row.id());var job=jdbc.query("SELECT * FROM reading_selection_translation WHERE id=?",mapper.jobs(),row.id()).getFirst();String result="GRAMMAR".equals(job.mode())?json.writeValueAsString(Map.of("scopeNote","这是时间状语从句片段。","mainClause",List.of(Map.of("quote","Omar","role","从句主语","explanation","名词。")),"clauses",List.of(Map.of("quote",job.text(),"role","时间状语从句","explanation","when引导。")),"clauseNote","当前仅选中从句，没有主句。","grammarPoints",List.of(Map.of("quote","moved to","explanation","表示搬到。")))):"当奥马尔搬到一个新城镇时";if("GRAMMAR".equals(job.mode()))jobs.complete(job,new com.englishhero.practice.review.DeepSeekReviewClient.TranslationResponse(result,"deepseek-flash",200L,20L));else jobs.completeBaidu(job,new BaiduTranslationClient.Result(result));jdbc.update("UPDATE reading_selection_translation SET created_at=DATE_SUB(created_at,INTERVAL 3 SECOND) WHERE id=?",job.id());}process.waitFor(300,TimeUnit.MILLISECONDS);}if(process.isAlive()){process.destroyForcibly();throw new AssertionError("Selection browser timeout");}assertThat(process.exitValue()).withFailMessage("Inspect ignored selection-translation/real-browser.log").isZero();assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM reading_selection_translation WHERE user_id=?",Integer.class,uid)).isEqualTo(2);}finally{Files.deleteIfExists(fixture);}}
}
